let particles=[]
let colors = "228822-44aa55-66cc77-57a165-88cc99".split("-").map(a=>"#"+a)

function setup() {
	createCanvas(1112,834);
	pixelDensity(2);
	background(180, 220, 255)
	for(let o=0;o<10;o++){
	let _x = random(width),_y=random(height)

	//bigger
	for(let i=0;i<15;i++){
		let newP = new Particle({
			p: createVector(_x-250,height+400),
			v: createVector(4,-2.84).rotate(random(0.05,0.05)),
			a: createVector(0,0),
			color: color(random(colors)),

		})
		particles.push(newP)

	}

	}

}

function draw() {
	rotate(2*PI)
	particles.forEach(p=>{
		p.update()
		p.draw()
	})
	particles= particles.filter(p=>p.life>0)

}

