// === Tab: particles ===
class Particle{
	constructor(args){
		let def = {
			p: createVector(0,0),
			v: createVector(0,0),
			a: createVector(0,0),
			r: 12, 
			life: 200,
		}
		Object.assign(def,args)
		Object.assign(this,def)
	}
	draw(){
		push()
		// blendMode(SCREEN)
			translate(this.p)
			noStroke()
			fill(this.color)
			if (this.life <= 2){
        fill(160, 100, 20);
			  circle(0,-this.r/2,this.r/2)
			}
			if (this.life <= 2) fill(140, 80, 20);
			circle(0,0,this.r)


		pop()
	}
	update(){
		this.life-=0.1

		if (this.r<4){
			this.life=2
			this.r=random(15,20) ///the flower at the end of the stem
		}

		this.p.add(this.v)
		this.v.add(this.a)

		this.r*=0.9954

		this.v.rotate(random(0.065,-0.0769))



	}
}

